// ("catac")
// >>> make_palindrome(("cata"))
// ("catac")
std::string make_palindrome(std::string string) {
    if (string.empty()) {
        return string;
    }
    int i = 0;
    int j = string.size() - 1;
    while (i < j) {
        if (string[i] != string[j]) {
            break;
        }
        i++;
        j--;
    }
    std::string prefix = string.substr(0, i);
    std::string suffix = string.substr(i, string.size() - i);
    return suffix + std::string(prefix.rbegin(), prefix.rend()) + suffix;

