// (std::make_tuple(2.0f, 2.0f))
std::tuple<float, float> find_closest_elements(std::vector<float> numbers) {
    assert(numbers.size() >= 2);
    float min_distance = std::numeric_limits<float>::max();
    float min_distance_i = 0;
    float min_distance_j = 0;
    for (int i = 0; i < numbers.size(); i++) {
        for (int j = i + 1; j < numbers.size(); j++) {
            float distance = std::abs(numbers[i] - numbers[j]);
            if (distance < min_distance) {
                min_distance = distance;
                min_distance_i = i;
                min_distance_j = j;
            }
        }
    }
    return std::make_tuple(numbers[min_distance_i], numbers[min_distance_j]);

