std::vector<long> remove_duplicates(std::vector<long> numbers) {
    std::vector<long> result;
    std::unordered_set<long> seen;
    for (long number : numbers) {
        if (seen.find(number) == seen.end()) {
            result.push_back(number);
            seen.insert(number);
        }
    }
    return result;

