    std::string result;
    for (auto c : string) {
        if (c >= 'a' && c <= 'z') {
            result += c - 'a' + 'A';
        } else if (c >= 'A' && c <= 'Z') {
            result += c - 'A' + 'a';
        } else {
            result += c;
        }
    }
    return result;

