// (131)
// >>> digitSum(("abcCd"))
// (67)
// >>> digitSum(("helloE"))
// (69)
// >>> digitSum(("woArBld"))
// (131)
// >>> digitSum(("aAaaaXa"))
// (153)
long digitSum(std::string s) {
  long sum = 0;
  for (auto c : s) {
    if (c >= 'A' && c <= 'Z') {
      sum += c;
    }
  }
  return sum;

