// Constrain:
// * 0 <= number <= 1000
// * 0 <= need <= 1000
// * 0 <= remaining <= 1000
// Have fun :)
std::vector<long> eat(long number, long need, long remaining) {
    std::vector<long> ans;
    if (number >= need) {
        ans.push_back(number);
        ans.push_back(remaining);
        return ans;
    }
    if (number + remaining < need) {
        ans.push_back(number + remaining);
        ans.push_back(0);
        return ans;
    }
    ans.push_back(need);
    ans.push_back(remaining - (need - number));
    return ans;

